export const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
export const clamp=(x,a,b)=>Math.max(a,Math.min(b,Number(x)||0));
export const colors=()=>Object.fromEntries(['exposure','contrast','highlights','shadows','whites','blacks','temperature','tint','saturation','vibrance'].map(k=>[k,0]));
export function project(){return{version:1,id:uid(),name:'Untitled film',media:[],clips:[],aspect:'Original',intent:'HIGH FASHION',texts:[],bgm:{volume:.3,fadeIn:0,fadeOut:0},analysis:[],export:{preset:'INSTAGRAM REELS',resolution:'1080p',fps:'30',quality:'High'}}}
export function clip(m){return{id:uid(),media:m.id,in:0,out:m.duration,speed:1,endSpeed:1,curve:'constant',scale:1,x:.5,y:.5,stabilization:'OFF',interpolation:'duplicate',hold:0,color:colors(),audio:{volume:1,mute:false,fadeIn:0,fadeOut:0}}}
export function speedAt(t,c){let a=c.speed??1,b=c.endSpeed??a;if(c.curve==='constant')return a;if(c.curve==='ease-in')t*=t;else if(c.curve==='ease-out')t=1-(1-t)**2;else if(c.curve==='ease-in-out')t=t*t*(3-2*t);return a+(b-a)*t}
export function timing(c){if(c.gap)return{nodes:[[0,0],[c.gap,c.gap]],pieces:[[0,c.gap,1,c.gap]],duration:c.gap};let d=c.out-c.in,n=c.curve==='constant'||c.speed===c.endSpeed?1:32,nodes=[[0,0]],pieces=[],elapsed=0;for(let i=0;i<n;i++){let x=d*i/n,y=d*(i+1)/n,s=speedAt((i+.5)/n,c),length=(y-x)/s;pieces.push([x,y,s,length]);elapsed+=length;nodes.push([y,elapsed])}return{nodes,pieces,duration:elapsed+(c.hold||0)}}
export function sourceOffset(t,c){let{nodes}=timing(c);for(let i=1;i<nodes.length;i++){let[x0,y0]=nodes[i-1],[x1,y1]=nodes[i];if(t<=y1)return x0+(t-y0)*(x1-x0)/(y1-y0)}return c.out-c.in}
export function outputOffset(t,c){let{nodes}=timing(c);for(let i=1;i<nodes.length;i++){let[x0,y0]=nodes[i-1],[x1,y1]=nodes[i];if(t<=x1)return y0+(t-x0)*(y1-y0)/(x1-x0)}return nodes.at(-1)[1]}
export function sequence(p){let time=0;return p.clips.map(c=>{let d=timing(c).duration,row={clip:c,start:time,end:time+d,duration:d};time+=d;return row})}
export function locate(p,t){let rows=sequence(p);return rows.find(r=>t>=r.start&&t<r.end)||rows.at(-1)}
export function total(p){return sequence(p).at(-1)?.end||0}
export function format(t){t=Math.max(0,t||0);let h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=Math.floor(t%60),f=Math.floor((t%1)*100);return[h,m,s].map(x=>String(x).padStart(2,'0')).join(':')+'.'+String(f).padStart(2,'0')}
export function sanitize(p){if(p?.version!==1||!Array.isArray(p.clips)||!Array.isArray(p.media)||p.clips.length>200||p.media.length>200)throw Error('対応していないプロジェクト形式です。');for(const c of p.clips){if(c.gap){c.gap=clamp(c.gap,.01,86400);continue}if(!p.media.some(m=>m.id===c.media))throw Error('素材情報が欠けています。');if(!Number.isFinite(c.in)||!Number.isFinite(c.out)||c.in<0||c.out<=c.in)throw Error('IN / OUT が無効です。');c.speed=clamp(c.speed??1,.05,20);c.endSpeed=clamp(c.endSpeed??c.speed,.05,20);c.color={...colors(),...c.color};c.audio={volume:1,mute:false,fadeIn:0,fadeOut:0,...c.audio};c.curve=c.curve||'constant'}return{...project(),...p,analysis:p.analysis||[],texts:p.texts||[],bgm:p.bgm||{volume:.3}}}
